<template>
  <section ref="root" class="learning-carousel portal-carousel" :class="{'carousel-held':held}" :style="{'--slide-progress':`${progress*100}%`,'--copy-direction':direction}" aria-roledescription="轮播" aria-label="编程学习主题" @pointerenter="hovered=true" @pointerleave="leavePointer" @focusin="focused=true" @focusout="leaveFocus" @keydown.left.prevent="move(-1)" @keydown.right.prevent="move(1)" @pointerdown="startSwipe" @pointerup="endSwipe">
    <div class="portal-stage" @pointermove="tiltArtwork">
      <div class="portal-world"><Transition name="fragment-backdrop"><img :key="active" class="world-backdrop" :src="slide.image" alt="" aria-hidden="true" /></Transition><div class="world-shade"></div><div class="portal-aperture"><FragmentImage :images="imageSources" :index="active" :alt="slide.alt" :code-label="slide.imageLabel" /></div></div>
      <div class="portal-grid" aria-hidden="true"></div><span class="portal-watermark" aria-hidden="true">0{{ active+1 }}</span>
      <div class="portal-copy-shell"><span class="portal-label"><i></i> LEARN · BUILD · EXPLORE</span><Transition name="creative-copy" mode="out-in"><div :key="active" class="carousel-copy" role="group" aria-roledescription="幻灯片" :aria-label="`${active+1} / ${slides.length}：${slide.title}`"><router-link class="carousel-text-link" :to="slide.to" :aria-label="`前往${slide.destination}：${slide.title}`"><span class="carousel-eyebrow">{{ slide.eyebrow }}</span><h1><span>{{ titleLines[0] }}</span><span class="portal-title-accent">{{ titleLines[1] }}</span></h1><p>{{ slide.description }}</p><span class="carousel-text-hint">前往{{ slide.destination }} <b aria-hidden="true">↗</b></span></router-link><div class="carousel-actions"><button @click="activate(slide.action)"><span class="portal-action-icon" aria-hidden="true">↗</span>{{ slide.button }}</button><router-link to="/library">查阅资料 <span aria-hidden="true">→</span></router-link></div></div></Transition><div class="portal-code-note"><span aria-hidden="true">&gt;_</span><code>{{ slide.code }}</code><i></i></div></div>
      <div class="portal-orbit-controls" aria-label="主题图片导航"><button v-for="(item,index) in slides" :key="item.image" class="orbit-stop" :class="{current:index===active}" :aria-label="`进入${labels[index]}主题`" :aria-current="index===active?'true':undefined" @click="choose(index)"><img :src="item.image" alt="" /><span>0{{ index+1 }}</span></button></div>
      <span class="portal-caption">{{ slide.caption }}</span><button class="next-art-preview" :aria-label="`预览下一张：${nextSlide.title}`" @click="move(1)"><span><small>NEXT CHAPTER</small>{{ nextSlide.label }}</span><b aria-hidden="true">↗</b></button>
    </div>
    <div class="carousel-controls"><div class="carousel-dots"><button v-for="(item,index) in slides" :key="item.eyebrow" :class="{selected:active===index}" :aria-label="`切换到第 ${index+1} 张：${item.title}`" :aria-current="active===index?'true':undefined" @click="choose(index)"><span class="chapter-index">0{{ index+1 }}</span><span class="chapter-label">{{ labels[index] }}</span><i class="chapter-progress" aria-hidden="true"></i></button></div><div class="carousel-playback"><span class="carousel-count">0{{ active+1 }} <i>/ {{ String(slides.length).padStart(2,'0') }}</i></span><button class="carousel-arrow" aria-label="上一张" @click="move(-1)">←</button><button class="carousel-arrow" aria-label="下一张" @click="move(1)">→</button><button class="carousel-pause" :aria-pressed="paused" :aria-label="paused?'继续自动轮播':'暂停自动轮播'" @click="paused=!paused">{{ paused?'播放':'暂停' }}</button></div></div>
  </section>
</template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import FragmentImage from './FragmentImage.vue'
import coding from '@/assets/learning-hero/coding.jpg'
import projects from '@/assets/learning-hero/projects.jpg'
import algorithms from '@/assets/learning-hero/algorithms.jpg'
import classroom from '@/assets/learning-hero/classroom.jpg'
import community from '@/assets/learning-hero/community.jpg'
const emit=defineEmits(['browse','path'])
const router=useRouter(),root=ref(null),active=ref(0),hovered=ref(false),focused=ref(false),paused=ref(false),progress=ref(0),direction=ref(1)
const slides=[
 {title:'从零基础到编程高手',lines:['从零基础','到编程高手'],label:'编程起步',eyebrow:'01 / START YOUR CODING JOURNEY',description:'系统化学习路径 · 实战项目驱动 · 实时编程练习',image:coding,alt:'自然光下的木质书桌，笔记本电脑显示代码，旁边放着手写本和咖啡杯',caption:'每一行代码，都是新的开始',button:'找一门课程',action:'browse',to:'/daily-checkin',destination:'每日打卡',code:'journey.start()',imageLabel:'hello, world'},
 {title:'让想法，成为运行中的作品',lines:['让想法，成为','运行中的作品'],label:'项目实践',eyebrow:'02 / BUILD SOMETHING REAL',description:'连接前端、后端与数据库，在动手实践中理解编程。',image:projects,alt:'真实开发工作台上的代码编辑器，屏幕后是彩色显示器，桌边摆着橙色小玩偶',caption:'从一个想法，到一个真实的项目',button:'动手写代码',action:'code',to:'/editor',destination:'编程器',code:'idea.build()',imageLabel:'build your idea'},
 {title:'把复杂问题，拆成清晰的步骤',lines:['把复杂问题，','拆成清晰的步骤'],label:'算法探索',eyebrow:'03 / THINK IN ALGORITHMS',description:'探索数据结构与算法，让每一步推理都有迹可循。',image:algorithms,alt:'开发者对照代码屏幕，在笔记本上手绘流程图、梳理解题步骤',caption:'连接知识，也连接解决问题的思路',button:'探索算法课程',action:'algorithm',to:'/library',destination:'资源库',code:'problem.solve()',imageLabel:'think in steps'},
 {title:'在每一次挑战中检验所学',lines:['在每一次挑战中','检验所学'],label:'班级挑战',eyebrow:'04 / PUT KNOWLEDGE TO THE TEST',description:'参加班级测试，在真实题目里发现进步，也找到需要补上的知识。',image:classroom,alt:'上海的书店自习空间里，读者在暖色书架环绕的长桌旁阅读学习',caption:'把学到的知识，变成自己的能力',button:'查看班级测试',action:'navigate',to:'/competition',destination:'班级测试',code:'challenge.accept()',imageLabel:'ready for a challenge'},
 {title:'让每一个问题都有新的思路',lines:['让每一个问题','都有新的思路'],label:'交流共学',eyebrow:'05 / LEARN BETTER TOGETHER',description:'分享代码与解题思路，在交流中发现新的方法，和同伴一起成长。',image:community,alt:'几位同伴围在同一台笔记本电脑旁，一起协作交流',caption:'分享一次思考，收获更多可能',button:'进入学习论坛',action:'navigate',to:'/forum',destination:'论坛',code:'ideas.share()',imageLabel:'learn better together'}]
const labels=slides.map(item=>item.label)
const slide=computed(()=>slides[active.value])
const nextSlide=computed(()=>slides[(active.value+1)%slides.length])
const imageSources=computed(()=>slides.map(item=>item.image))
const titleLines=computed(()=>slide.value.lines)
const held=computed(()=>hovered.value || focused.value || paused.value)
let timer,observer,visible=true,lastTick=0,elapsed=0,pointerFrame=0,swipe=null
function choose(index,travel){const next=(index+slides.length)%slides.length;if(next===active.value)return;direction.value=travel || (next>active.value?1:-1);active.value=next;elapsed=0;progress.value=0}
function move(travel){choose(active.value+travel,travel)}
function tick(){const time=performance.now(),delta=Math.min(250,time-lastTick);lastTick=time;if(document.hidden || !visible || held.value)return;elapsed+=delta;progress.value=Math.min(1,elapsed/6500);if(elapsed>=6500)move(1)}
function leaveFocus(event){if(!root.value?.contains(event.relatedTarget))focused.value=false}
function activate(action){if(action==='code')router.push('/editor');else if(action==='algorithm')emit('path');else if(action==='browse')emit('browse');else router.push(slide.value.to)}
function tiltArtwork(event){if(event.pointerType!=='mouse'||pointerFrame)return;const rect=event.currentTarget.getBoundingClientRect();if(!rect.width||!rect.height)return;const x=Math.max(-.5,Math.min(.5,(event.clientX-rect.left)/rect.width-.5)),y=Math.max(-.5,Math.min(.5,(event.clientY-rect.top)/rect.height-.5));pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;root.value?.style.setProperty('--art-rx',`${-y*5}deg`);root.value?.style.setProperty('--art-ry',`${x*7}deg`)})}
function leavePointer(){hovered.value=false;cancelAnimationFrame(pointerFrame);pointerFrame=0;root.value?.style.removeProperty('--art-rx');root.value?.style.removeProperty('--art-ry');swipe=null}
function startSwipe(event){if(event.pointerType==='touch')swipe={x:event.clientX,y:event.clientY}}
function endSwipe(event){if(!swipe)return;const dx=event.clientX-swipe.x,dy=event.clientY-swipe.y;swipe=null;if(Math.abs(dx)>45 && Math.abs(dx)>Math.abs(dy)*1.4){event.preventDefault();move(dx<0?1:-1)}}
onMounted(()=>{lastTick=performance.now();timer=setInterval(tick,100);if(typeof IntersectionObserver!=='undefined'){observer=new IntersectionObserver(entries=>{visible=entries[0]?.isIntersecting??true});observer.observe(root.value)}})
onBeforeUnmount(()=>{clearInterval(timer);observer?.disconnect();cancelAnimationFrame(pointerFrame)})
</script><style scoped>
